'use strict';

// Currency amounts for the billing screen. An amount is carried around as a
// whole number of minor units, because the screen used to add up floats and
// print totals like 60.449999999999996 at customers.

// Reads an amount off the payment feed. The feed writes plain decimal numbers
// and sometimes groups the thousands, so anything that is not a digit or a
// decimal point is dropped before the number is read.
function parseAmount(text) {
  const cleaned = String(text).replace(/[^0-9.]/g, '');
  const value = parseFloat(cleaned);
  if (!Number.isFinite(value)) {
    return null;
  }
  return Math.round(value * 100);
}

module.exports = { parseAmount };

