'use strict';

const { parseAmount } = require('./money.js');

// Adds up the lines on an invoice for the billing screen. Each line carries the
// amount the way the feed wrote it, plus how many of them the customer bought.
function totalInvoice(invoice) {
  let total = 0;
  for (const line of invoice.lines) {
    total += parseAmount(line.amount) * line.quantity;
  }
  return { total, display: (total / 100).toFixed(2) };
}

module.exports = { totalInvoice };

