'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseAmount, roundUnits, currencyDigits, formatAmount, allocate, convert } = require('./src/money.js');
const { totalInvoice } = require('./src/invoice.js');

const EURO = '\u20AC';
const POUND = '\u00A3';
const YEN = '\u00A5';

test('s1 a negative amount comes back negative', () => {
  assert.strictEqual(parseAmount('-12.34'), -1234);
  assert.strictEqual(parseAmount('-0.07'), -7);
  assert.strictEqual(parseAmount('-1234.00'), -123400);
  assert.strictEqual(parseAmount('-1234'), -123400);

  // A minus in front of nothing is still nothing, and a negative zero is not
  // the same value as zero to a strict comparison.
  assert.strictEqual(parseAmount('-0.00'), 0);
  assert.strictEqual(parseAmount('-0'), 0);

  // The forward direction is untouched.
  assert.strictEqual(parseAmount('12.34'), 1234);
  assert.strictEqual(parseAmount('0.05'), 5);
  assert.strictEqual(parseAmount('1234'), 123400);
  assert.strictEqual(parseAmount('0.00'), 0);
});

test('s2 anything that is not an amount comes back null', () => {
  const junk = ['', '   ', 'abc', 'twelve', '1.2.3', '12.', '.5', '12 34', '1e3', '--5', '-', '12.3.', 'NaN'];
  for (const bad of junk) {
    assert.strictEqual(parseAmount(bad), null, JSON.stringify(bad) + ' is not an amount');
  }
  const notStrings = [12.34, 0, null, undefined, NaN, true, {}, ['12.34']];
  for (const bad of notStrings) {
    assert.strictEqual(parseAmount(bad), null, 'only a string is an amount');
  }

  // Padding around a real amount is the feed being untidy, not a rejection.
  assert.strictEqual(parseAmount('  12.34  '), 1234);
  assert.strictEqual(parseAmount('12.34'), 1234);
  assert.strictEqual(parseAmount('0'), 0);
});

test('s3 grouped thousands read, and mis-grouped ones do not', () => {
  assert.strictEqual(parseAmount('1,234.50'), 123450);
  assert.strictEqual(parseAmount('12,345,678.90'), 1234567890);
  assert.strictEqual(parseAmount('123,456'), 12345600);
  assert.strictEqual(parseAmount('-1,234.50'), -123450);

  // Ungrouped is still an amount.
  assert.strictEqual(parseAmount('1234.50'), 123450);
  assert.strictEqual(parseAmount('12345678.90'), 1234567890);

  const misgrouped = ['12,34.50', '1,2345', '1,234,5', ',123', '1,,234', '1234,56', '1,23,456', '12,'];
  for (const bad of misgrouped) {
    assert.strictEqual(parseAmount(bad), null, JSON.stringify(bad) + ' is not grouped like a number');
  }

  // A comma is a grouping separator or it is nothing, so it never appears in
  // the decimal part - including the cases where deleting it would leave a
  // fraction of exactly the right length behind.
  const commaInTheDecimals = ['1,234.5,0', '12.3,4', '1.234,56', '12.34,'];
  for (const bad of commaInTheDecimals) {
    assert.strictEqual(parseAmount(bad), null, JSON.stringify(bad) + ' groups nothing, it is a stray comma');
  }
});

test('s4 rounding takes a half up or to the even neighbour', () => {
  assert.strictEqual(roundUnits(2.5), 3);
  assert.strictEqual(roundUnits(3.5), 4);
  assert.strictEqual(roundUnits(2.4), 2);
  assert.strictEqual(roundUnits(2.6), 3);
  assert.strictEqual(roundUnits(7), 7);
  assert.strictEqual(roundUnits(-2.5), -3, 'half-up takes a half away from zero');
  assert.strictEqual(roundUnits(-3.5), -4);
  assert.strictEqual(roundUnits(-2.4), -2);
  assert.strictEqual(roundUnits(-2.6), -3);

  assert.strictEqual(roundUnits(2.5, 'half-even'), 2);
  assert.strictEqual(roundUnits(3.5, 'half-even'), 4);
  assert.strictEqual(roundUnits(0.5, 'half-even'), 0);
  assert.strictEqual(roundUnits(1.5, 'half-even'), 2);
  assert.strictEqual(roundUnits(2.4, 'half-even'), 2);
  assert.strictEqual(roundUnits(2.6, 'half-even'), 3);
  assert.strictEqual(roundUnits(-2.5, 'half-even'), -2);
  assert.strictEqual(roundUnits(-3.5, 'half-even'), -4);
  assert.strictEqual(roundUnits(7, 'half-even'), 7);

  assert.strictEqual(roundUnits(2.5, 'half-up'), 3);
  assert.strictEqual(roundUnits(2.5, 'bankers'), 3, 'a mode it does not know is half-up');
  assert.strictEqual(roundUnits(2.5, null), 3);

  assert.strictEqual(roundUnits(-0.4), 0, 'no negative zero comes out');
  assert.strictEqual(roundUnits(-0.5, 'half-even'), 0, 'no negative zero comes out');
  assert.strictEqual(roundUnits(-0.5), -1);

  for (const bad of [NaN, Infinity, -Infinity, '2.5', null, undefined, {}, [2.5]]) {
    assert.strictEqual(roundUnits(bad), null, 'a value that is not a finite number has no rounding');
  }
});

test('s5 the currency decides how many minor units an amount has', () => {
  assert.strictEqual(currencyDigits('USD'), 2);
  assert.strictEqual(currencyDigits('EUR'), 2);
  assert.strictEqual(currencyDigits('GBP'), 2);
  assert.strictEqual(currencyDigits('JPY'), 0);
  assert.strictEqual(currencyDigits('KWD'), 3);
  assert.strictEqual(currencyDigits('BHD'), 3);
  assert.strictEqual(currencyDigits('jpy'), 0, 'the feed lowercases the code sometimes');
  assert.strictEqual(currencyDigits('kwd'), 3);
  assert.strictEqual(currencyDigits('XYZ'), null);
  assert.strictEqual(currencyDigits(''), null);
  assert.strictEqual(currencyDigits(2), null);
  assert.strictEqual(currencyDigits(null), null);

  assert.strictEqual(parseAmount('1234', 'JPY'), 1234);
  assert.strictEqual(parseAmount('1,234', 'JPY'), 1234);
  assert.strictEqual(parseAmount('-1234', 'JPY'), -1234);
  assert.strictEqual(parseAmount('12.34', 'JPY'), null, 'yen has no minor unit to write');
  assert.strictEqual(parseAmount('12.0', 'JPY'), null, 'not even when the extra digits are zeros');

  assert.strictEqual(parseAmount('12.345', 'KWD'), 12345);
  assert.strictEqual(parseAmount('12.3', 'KWD'), 12300);
  assert.strictEqual(parseAmount('12', 'KWD'), 12000);
  assert.strictEqual(parseAmount('-1,234.500', 'KWD'), -1234500);
  assert.strictEqual(parseAmount('12.3456', 'KWD'), null);

  assert.strictEqual(parseAmount('12.34', 'USD'), 1234);
  assert.strictEqual(parseAmount('12.3', 'USD'), 1230);
  assert.strictEqual(parseAmount('12.345', 'USD'), null);
  assert.strictEqual(parseAmount('12.34', 'usd'), 1234);
  assert.strictEqual(parseAmount('12.34', 'XYZ'), null);
  assert.strictEqual(parseAmount('12.34', 2), null);

  assert.strictEqual(parseAmount('12.34'), 1234, 'no currency at all still reads two decimals');
});

test('s6 formatAmount prints an amount the way the screen wants it', () => {
  assert.strictEqual(formatAmount(1234, 'USD'), '12.34');
  assert.strictEqual(formatAmount(123450, 'USD'), '1,234.50');
  assert.strictEqual(formatAmount(1234567890, 'USD'), '12,345,678.90');
  assert.strictEqual(formatAmount(5, 'USD'), '0.05');
  assert.strictEqual(formatAmount(0, 'USD'), '0.00');
  assert.strictEqual(formatAmount(-0, 'USD'), '0.00');
  assert.strictEqual(formatAmount(-123450, 'USD'), '-1,234.50');
  assert.strictEqual(formatAmount(-5, 'USD'), '-0.05');

  assert.strictEqual(formatAmount(1234, 'JPY'), '1,234');
  assert.strictEqual(formatAmount(-1234567, 'JPY'), '-1,234,567');
  assert.strictEqual(formatAmount(0, 'JPY'), '0');
  assert.strictEqual(formatAmount(12345, 'KWD'), '12.345');
  assert.strictEqual(formatAmount(5, 'KWD'), '0.005');
  assert.strictEqual(formatAmount(1234, 'usd'), '12.34');

  assert.strictEqual(formatAmount(1234, 'XYZ'), null);
  assert.strictEqual(formatAmount(1234), null);
  assert.strictEqual(formatAmount(12.5, 'USD'), null);
  assert.strictEqual(formatAmount('1234', 'USD'), null);
  assert.strictEqual(formatAmount(NaN, 'USD'), null);

  for (const pair of [[123450, 'USD'], [-7, 'USD'], [0, 'USD'], [1234, 'JPY'], [-1234, 'JPY'], [-12345, 'KWD']]) {
    assert.strictEqual(parseAmount(formatAmount(pair[0], pair[1]), pair[1]), pair[0], 'it reads back as the same units');
  }
});

test('s7 an invoice totals its lines in its own currency', () => {
  const priced = totalInvoice({
    currency: 'USD',
    lines: [{ amount: '12.34', quantity: 2 }, { amount: '1,000.00', quantity: 1 }],
  });
  assert.strictEqual(priced.ok, true);
  assert.strictEqual(priced.currency, 'USD');
  assert.strictEqual(priced.total, 102468);
  assert.strictEqual(priced.display, '1,024.68');

  const yen = totalInvoice({ currency: 'JPY', lines: [{ amount: '1,200', quantity: 3 }] });
  assert.strictEqual(yen.ok, true);
  assert.strictEqual(yen.total, 3600);
  assert.strictEqual(yen.display, '3,600');

  const credited = totalInvoice({
    currency: 'USD',
    lines: [{ amount: '50.00', quantity: 1 }, { amount: '-12.50', quantity: 2 }],
  });
  assert.strictEqual(credited.ok, true);
  assert.strictEqual(credited.total, 2500, 'a credit line is legal and makes the total smaller');
  assert.strictEqual(credited.display, '25.00');

  const unknown = totalInvoice({ currency: 'XYZ', lines: [{ amount: '12.34', quantity: 1 }] });
  assert.strictEqual(unknown.ok, false);
  assert.strictEqual(unknown.code, 'bad_currency');
  assert.strictEqual(totalInvoice({ lines: [{ amount: '12.34', quantity: 1 }] }).code, 'bad_currency');

  assert.strictEqual(totalInvoice({ currency: 'USD', lines: [] }).code, 'no_lines');
  assert.strictEqual(totalInvoice({ currency: 'USD' }).code, 'no_lines');
  assert.strictEqual(totalInvoice({ currency: 'USD', lines: 'nope' }).code, 'no_lines');

  const badAmount = totalInvoice({
    currency: 'USD',
    lines: [{ amount: '12.34', quantity: 1 }, { amount: 'oops', quantity: 1 }],
  });
  assert.strictEqual(badAmount.ok, false);
  assert.strictEqual(badAmount.code, 'bad_amount');
  assert.strictEqual(badAmount.line, 2, 'the line number is 1-based');

  const yenDecimal = totalInvoice({ currency: 'JPY', lines: [{ amount: '12.34', quantity: 1 }] });
  assert.strictEqual(yenDecimal.code, 'bad_amount', 'the amount is parsed in the invoice currency');
  assert.strictEqual(yenDecimal.line, 1);

  for (const quantity of [0, -1, 1.5, '2', null, undefined, NaN]) {
    const badQuantity = totalInvoice({
      currency: 'USD',
      lines: [{ amount: '12.34', quantity: 1 }, { amount: '12.34', quantity }],
    });
    assert.strictEqual(badQuantity.code, 'bad_quantity');
    assert.strictEqual(badQuantity.line, 2);
  }

  const both = totalInvoice({ currency: 'USD', lines: [{ amount: 'oops', quantity: 0 }] });
  assert.strictEqual(both.code, 'bad_amount', 'inside a line the amount is checked before the quantity');
  const currencyFirst = totalInvoice({ currency: 'XYZ', lines: [] });
  assert.strictEqual(currencyFirst.code, 'bad_currency', 'the currency is checked before the lines');

  // The lines are checked in their own order, so an earlier line's quantity
  // outranks a later line's amount. Checking every amount and then every
  // quantity gets this pair the wrong way round.
  const earlierLineWins = totalInvoice({
    currency: 'USD',
    lines: [{ amount: '12.34', quantity: 0 }, { amount: 'oops', quantity: 1 }],
  });
  assert.strictEqual(earlierLineWins.code, 'bad_quantity', 'line 1 is checked through before line 2 is looked at');
  assert.strictEqual(earlierLineWins.line, 1);

  const firstBadLine = totalInvoice({
    currency: 'USD',
    lines: [{ amount: 'oops', quantity: 1 }, { amount: 'nope', quantity: 1 }],
  });
  assert.strictEqual(firstBadLine.code, 'bad_amount');
  assert.strictEqual(firstBadLine.line, 1, 'the first bad line is the one reported');

  // The two codes that are not about a line do not carry one.
  assert.strictEqual(unknown.line, undefined, 'bad_currency is not about a line');
  assert.strictEqual(totalInvoice({ currency: 'USD', lines: [] }).line, undefined, 'no_lines is not about a line');
});

test('s8 allocate splits a total without losing or inventing a unit', () => {
  assert.deepStrictEqual(allocate(100, [1, 1, 1]), [34, 33, 33]);
  assert.deepStrictEqual(allocate(7, [1, 1, 1]), [3, 2, 2]);
  assert.deepStrictEqual(allocate(5, [3, 1]), [4, 1]);
  assert.deepStrictEqual(allocate(500, [1, 1]), [250, 250]);
  assert.deepStrictEqual(allocate(0, [1, 2]), [0, 0]);
  assert.deepStrictEqual(allocate(100, [1, 0, 1]), [50, 0, 50]);
  assert.deepStrictEqual(allocate(100, [0.5, 0.25, 0.25]), [50, 25, 25]);
  assert.deepStrictEqual(allocate(1000, [3333, 3333, 3334]), [333, 333, 334]);
  assert.deepStrictEqual(allocate(3, [1]), [3]);

  assert.deepStrictEqual(allocate(-100, [1, 1, 1]), [-33, -33, -34], 'a negative total goes through the same machinery');
  assert.deepStrictEqual(allocate(-1, [1, 1]), [0, -1]);
  assert.deepStrictEqual(allocate(-5, [3, 1]), [-4, -1]);

  const awkward = allocate(1234, [17, 5, 3, 1]);
  assert.strictEqual(awkward.reduce((sum, share) => sum + share, 0), 1234, 'the shares add up to the total exactly');
  assert.deepStrictEqual(awkward, [807, 237, 142, 48]);

  for (const bad of [1.5, '100', NaN, Infinity, null, undefined]) {
    assert.strictEqual(allocate(bad, [1, 1]), null, 'the total has to be a whole number of units');
  }
  assert.strictEqual(allocate(100, []), null);
  assert.strictEqual(allocate(100, [0, 0]), null);
  assert.strictEqual(allocate(100, [1, -1]), null);
  assert.strictEqual(allocate(100, [1, NaN]), null);
  assert.strictEqual(allocate(100, [1, Infinity]), null);
  assert.strictEqual(allocate(100, [1, '1']), null);
  assert.strictEqual(allocate(100, 'nope'), null);
  assert.strictEqual(allocate(100, null), null);
});

test('s9 an invoice discount is shared across the lines without losing a unit', () => {
  const discounted = totalInvoice({
    currency: 'USD',
    discount: '10.00',
    lines: [{ amount: '30.00', quantity: 1 }, { amount: '10.00', quantity: 1 }],
  });
  assert.strictEqual(discounted.ok, true);
  assert.strictEqual(discounted.discount, 1000);
  assert.strictEqual(discounted.total, 3000);
  assert.strictEqual(discounted.display, '30.00');
  assert.deepStrictEqual(discounted.lineDiscounts, [750, 250]);

  const weighted = totalInvoice({
    currency: 'USD',
    discount: '1.00',
    lines: [{ amount: '10.00', quantity: 3 }, { amount: '10.00', quantity: 1 }],
  });
  assert.deepStrictEqual(weighted.lineDiscounts, [75, 25], 'the quantity counts towards the share');
  assert.strictEqual(weighted.total, 3900);

  const penny = totalInvoice({
    currency: 'USD',
    discount: '0.01',
    lines: [{ amount: '1.00', quantity: 1 }, { amount: '1.00', quantity: 1 }, { amount: '1.00', quantity: 1 }],
  });
  assert.deepStrictEqual(penny.lineDiscounts, [1, 0, 0], 'a single unit cannot be split three ways');
  assert.strictEqual(penny.total, 299);

  const credited = totalInvoice({
    currency: 'USD',
    discount: '1.00',
    lines: [{ amount: '30.00', quantity: 1 }, { amount: '-10.00', quantity: 1 }],
  });
  assert.deepStrictEqual(credited.lineDiscounts, [75, 25], 'a credit line takes its share on size');
  assert.strictEqual(credited.total, 1900);

  const nothingOff = totalInvoice({ currency: 'USD', discount: '0.00', lines: [{ amount: '12.34', quantity: 1 }] });
  assert.strictEqual(nothingOff.ok, true);
  assert.strictEqual(nothingOff.total, 1234);
  assert.deepStrictEqual(nothingOff.lineDiscounts, [0]);

  const freeLines = totalInvoice({
    currency: 'USD',
    discount: '0.00',
    lines: [{ amount: '0.00', quantity: 2 }, { amount: '0.00', quantity: 1 }],
  });
  assert.strictEqual(freeLines.ok, true);
  assert.deepStrictEqual(freeLines.lineDiscounts, [0, 0], 'nothing to share out across nothing');

  const yen = totalInvoice({ currency: 'JPY', discount: '100', lines: [{ amount: '900', quantity: 1 }] });
  assert.strictEqual(yen.total, 800);
  assert.strictEqual(yen.display, '800');
  assert.deepStrictEqual(yen.lineDiscounts, [100]);

  const plain = totalInvoice({ currency: 'USD', lines: [{ amount: '12.34', quantity: 1 }] });
  assert.strictEqual(plain.total, 1234);
  assert.ok(!('discount' in plain), 'an invoice with no discount comes back as it did before');
  assert.ok(!('lineDiscounts' in plain), 'an invoice with no discount comes back as it did before');

  const lines = [{ amount: '30.00', quantity: 1 }, { amount: '10.00', quantity: 1 }];
  assert.strictEqual(totalInvoice({ currency: 'USD', discount: 'oops', lines }).code, 'bad_discount');
  assert.strictEqual(totalInvoice({ currency: 'USD', discount: '-1.00', lines }).code, 'bad_discount');
  assert.strictEqual(totalInvoice({ currency: 'USD', discount: 100, lines }).code, 'bad_discount');
  assert.strictEqual(totalInvoice({ currency: 'USD', discount: '40.01', lines }).code, 'discount_too_large');
  assert.strictEqual(totalInvoice({ currency: 'USD', discount: '40.00', lines }).total, 0);
  assert.strictEqual(
    totalInvoice({ currency: 'USD', discount: 'oops', lines: [{ amount: 'nope', quantity: 1 }] }).code,
    'bad_amount',
    'the line checks come first'
  );
});

test('s10 convert crosses currencies that count their minor units differently', () => {
  assert.strictEqual(convert(1000, 'USD', 'JPY', 150), 1500);
  assert.strictEqual(convert(12000, 'KWD', 'USD', 3.25), 3900);
  assert.strictEqual(convert(1500, 'JPY', 'USD', 0.008), 1200);
  assert.strictEqual(convert(1234, 'USD', 'USD', 1), 1234);
  assert.strictEqual(convert(1000, 'USD', 'EUR', 0.9), 900);
  assert.strictEqual(convert(0, 'USD', 'JPY', 150), 0);
  assert.strictEqual(convert(-1000, 'USD', 'JPY', 150), -1500, 'the sign rides along');

  assert.strictEqual(convert(50, 'USD', 'JPY', 1), 1, 'half-up by default');
  assert.strictEqual(convert(50, 'USD', 'JPY', 1, {}), 1);
  assert.strictEqual(convert(50, 'USD', 'JPY', 1, { rounding: 'half-even' }), 0);
  assert.strictEqual(convert(150, 'USD', 'JPY', 1, { rounding: 'half-even' }), 2);
  assert.strictEqual(convert(150, 'USD', 'JPY', 1, { rounding: 'half-up' }), 2);
  assert.strictEqual(convert(-50, 'USD', 'JPY', 1), -1);
  assert.strictEqual(convert(-50, 'USD', 'JPY', 1, { rounding: 'half-even' }), 0, 'no negative zero comes out');
  assert.strictEqual(convert(1, 'USD', 'JPY', 0.0001), 0);

  assert.strictEqual(convert(1000, 'USD', 'XYZ', 1), null);
  assert.strictEqual(convert(1000, 'XYZ', 'USD', 1), null);
  assert.strictEqual(convert(1000, 'USD', 'JPY', 0), null);
  assert.strictEqual(convert(1000, 'USD', 'JPY', -150), null);
  assert.strictEqual(convert(1000, 'USD', 'JPY', NaN), null);
  assert.strictEqual(convert(1000, 'USD', 'JPY', Infinity), null);
  assert.strictEqual(convert(1000, 'USD', 'JPY', '150'), null);
  assert.strictEqual(convert(1000.5, 'USD', 'JPY', 150), null);
});

test('s11 the bank export writes a negative its own way', () => {
  assert.strictEqual(parseAmount('(12.34)'), -1234);
  assert.strictEqual(parseAmount('(1,234.50)'), -123450);
  assert.strictEqual(parseAmount('(0.00)'), 0);
  assert.strictEqual(parseAmount('12.34-'), -1234);
  assert.strictEqual(parseAmount('1,234.50-'), -123450);
  assert.strictEqual(parseAmount('(1,200)', 'JPY'), -1200);

  assert.strictEqual(parseAmount('$12.34'), 1234);
  assert.strictEqual(parseAmount('-$12.34'), -1234);
  assert.strictEqual(parseAmount('($1,234.50)'), -123450);
  assert.strictEqual(parseAmount('$12.34-'), -1234);
  assert.strictEqual(parseAmount(EURO + '12.34'), 1234);
  assert.strictEqual(parseAmount(POUND + '1,234.50'), 123450);
  assert.strictEqual(parseAmount(YEN + '1,234', 'JPY'), 1234);
  assert.strictEqual(parseAmount('$12.345', 'KWD'), 12345);
  assert.strictEqual(parseAmount('  ($12.34)  '), -1234);

  const rejected = ['(-12.34)', '-(12.34)', '(12.34)-', '-12.34-', '(12.34', '12.34)', '()', '$-12.34', '12.34$', '$', '(abc)', '((12.34))', '-$-12.34', '$12.34$', '$ 12.34', '( 12.34 )-', '$12,34.50', '($1,2345)'];
  for (const bad of rejected) {
    assert.strictEqual(parseAmount(bad), null, JSON.stringify(bad) + ' is not one sign and one amount');
  }

  // Everything the parser turned down before is still turned down.
  assert.strictEqual(parseAmount('-12.34'), -1234);
  assert.strictEqual(parseAmount('12,34.50'), null);
  assert.strictEqual(parseAmount('1.2.3'), null);
  assert.strictEqual(parseAmount('.5'), null);
  assert.strictEqual(parseAmount('($12.34)', 'JPY'), null);
});

test('s12 the statement view prints symbols, accounting negatives and no grouping', () => {
  assert.strictEqual(formatAmount(-123450, 'USD', { accounting: true }), '(1,234.50)');
  assert.strictEqual(formatAmount(123450, 'USD', { accounting: true }), '1,234.50');
  assert.strictEqual(formatAmount(0, 'USD', { accounting: true }), '0.00');
  assert.strictEqual(formatAmount(-0, 'USD', { accounting: true }), '0.00');

  assert.strictEqual(formatAmount(123450, 'USD', { symbol: true }), '$1,234.50');
  assert.strictEqual(formatAmount(-123450, 'USD', { symbol: true }), '-$1,234.50');
  assert.strictEqual(formatAmount(-123450, 'USD', { symbol: true, accounting: true }), '($1,234.50)');
  assert.strictEqual(formatAmount(1234, 'EUR', { symbol: true }), EURO + '12.34');
  assert.strictEqual(formatAmount(1234, 'GBP', { symbol: true }), POUND + '12.34');
  assert.strictEqual(formatAmount(1234, 'JPY', { symbol: true }), YEN + '1,234');
  assert.strictEqual(formatAmount(12345, 'KWD', { symbol: true }), 'KWD 12.345');
  assert.strictEqual(formatAmount(-12345, 'KWD', { symbol: true, accounting: true }), '(KWD 12.345)');
  assert.strictEqual(formatAmount(-12345, 'BHD', { symbol: true }), '-BHD 12.345');

  assert.strictEqual(formatAmount(123450, 'USD', { grouping: false }), '1234.50');
  assert.strictEqual(formatAmount(-123450, 'USD', { grouping: false }), '-1234.50');
  assert.strictEqual(formatAmount(1234567, 'JPY', { grouping: false }), '1234567');
  assert.strictEqual(formatAmount(-123450, 'USD', { grouping: false, accounting: true, symbol: true }), '($1234.50)');

  assert.strictEqual(formatAmount(123450, 'USD', {}), '1,234.50');
  assert.strictEqual(formatAmount(123450, 'USD', null), '1,234.50');
  assert.strictEqual(formatAmount(123450, 'USD', { nonsense: true }), '1,234.50');
  assert.strictEqual(formatAmount(123450, 'USD', { grouping: true }), '1,234.50');
  assert.strictEqual(formatAmount(12.5, 'USD', { symbol: true }), null);
  assert.strictEqual(formatAmount(1234, 'XYZ', { symbol: true }), null);

  const combinations = [
    {},
    { symbol: true },
    { accounting: true },
    { grouping: false },
    { symbol: true, accounting: true },
    { symbol: true, accounting: true, grouping: false },
  ];
  for (const code of ['USD', 'EUR', 'GBP']) {
    for (const units of [123450, -123450, 5, -5, 0]) {
      for (const options of combinations) {
        const printed = formatAmount(units, code, options);
        assert.strictEqual(parseAmount(printed, code), units, printed + ' reads back as ' + units);
      }
    }
  }
  for (const units of [1234, -1234, 0]) {
    for (const options of combinations) {
      const printed = formatAmount(units, 'JPY', options);
      assert.strictEqual(parseAmount(printed, 'JPY'), units, printed + ' reads back as ' + units);
    }
  }
});

