'use strict';

// Currency amounts for the billing screen. An amount is a whole number of minor
// units in its own currency - cents in USD, whole yen in JPY, fils in KWD - and
// nothing in here ever holds money in a float.

const CURRENCIES = {
  USD: { digits: 2, symbol: '$' },
  EUR: { digits: 2, symbol: '\u20AC' },
  GBP: { digits: 2, symbol: '\u00A3' },
  JPY: { digits: 0, symbol: '\u00A5' },
  KWD: { digits: 3, symbol: null },
  BHD: { digits: 3, symbol: null },
};

const SYMBOLS = ['$', '\u20AC', '\u00A3', '\u00A5'];
const GROUPED = /^\d{1,3}(,\d{3})*$/;
const PLAIN = /^\d+$/;
const DEFAULT_DIGITS = 2;

// Nothing leaves this module as a negative zero: a total compared against a
// stored one has to match, and -0 is not 0 to a strict comparison.
function noNegativeZero(value) {
  return value === 0 ? 0 : value;
}

function entryFor(code) {
  if (typeof code !== 'string') return null;
  const found = CURRENCIES[code.trim().toUpperCase()];
  return found || null;
}

function currencyDigits(code) {
  const entry = entryFor(code);
  return entry ? entry.digits : null;
}

// Whole minor units from a possibly fractional count. half-up sends a half away
// from zero; half-even sends it to whichever neighbour is even. Anything else,
// including no mode at all, is half-up.
function roundUnits(value, mode) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  const sign = value < 0 ? -1 : 1;
  const size = Math.abs(value);
  const below = Math.floor(size);
  const part = size - below;
  let whole;
  if (part > 0.5) whole = below + 1;
  else if (part < 0.5) whole = below;
  else if (mode === 'half-even') whole = below % 2 === 0 ? below : below + 1;
  else whole = below + 1;
  return noNegativeZero(sign * whole);
}

function digitsFor(currency) {
  if (currency === undefined || currency === null) return DEFAULT_DIGITS;
  return currencyDigits(currency);
}

// One amount off a feed. Handles the accountants' spellings of a negative -
// leading minus, trailing minus, wrapping parentheses - of which exactly one is
// allowed, and an optional currency symbol sitting inside the sign.
function parseAmount(text, currency) {
  const digits = digitsFor(currency);
  if (digits === null) return null;
  if (typeof text !== 'string') return null;

  let body = text.trim();
  if (body === '') return null;

  let negative = false;
  if (body.charAt(0) === '(' && body.charAt(body.length - 1) === ')' && body.length >= 2) {
    negative = true;
    body = body.slice(1, -1).trim();
  } else if (body.indexOf('(') >= 0 || body.indexOf(')') >= 0) {
    return null;
  }

  if (body.charAt(0) === '-') {
    if (negative) return null;
    negative = true;
    body = body.slice(1);
  }
  if (body.charAt(body.length - 1) === '-') {
    if (negative) return null;
    negative = true;
    body = body.slice(0, -1);
  }
  if (body.length > 0 && SYMBOLS.indexOf(body.charAt(0)) >= 0) {
    body = body.slice(1);
  }

  const parts = body.split('.');
  if (parts.length > 2) return null;
  const whole = parts[0];
  const fraction = parts.length === 2 ? parts[1] : '';
  if (!PLAIN.test(whole) && !GROUPED.test(whole)) return null;
  if (parts.length === 2 && !PLAIN.test(fraction)) return null;
  if (fraction.length > digits) return null;

  const scaled = whole.split(',').join('') + fraction.padEnd(digits, '0');
  const units = Number(scaled);
  if (!Number.isFinite(units)) return null;
  return noNegativeZero(negative ? -units : units);
}

function group(whole) {
  let out = '';
  for (let i = 0; i < whole.length; i += 1) {
    if (i > 0 && (whole.length - i) % 3 === 0) out += ',';
    out += whole.charAt(i);
  }
  return out;
}

// An amount as the screen prints it. The symbol sits inside the sign, so a
// minus goes in front of it and accounting parentheses go around it.
function formatAmount(units, currency, options) {
  if (typeof units !== 'number' || !Number.isInteger(units)) return null;
  const entry = entryFor(currency);
  if (entry === null) return null;
  const opts = options && typeof options === 'object' ? options : {};
  const digits = entry.digits;

  const size = Math.abs(units);
  const padded = String(size).padStart(digits + 1, '0');
  let whole = digits === 0 ? padded : padded.slice(0, padded.length - digits);
  const fraction = digits === 0 ? '' : padded.slice(padded.length - digits);
  if (opts.grouping !== false) whole = group(whole);

  let out = whole + (digits === 0 ? '' : '.' + fraction);
  if (opts.symbol) {
    out = (entry.symbol === null ? String(currency).trim().toUpperCase() + ' ' : entry.symbol) + out;
  }
  if (units >= 0) return out;
  return opts.accounting ? '(' + out + ')' : '-' + out;
}

// Splits a whole number of minor units across weighted shares without losing or
// inventing one. Each share takes the largest whole number not above its exact
// share; the units left over go to the biggest fractional parts, earliest first.
function allocate(units, weights) {
  if (typeof units !== 'number' || !Number.isInteger(units)) return null;
  if (!Array.isArray(weights) || weights.length === 0) return null;
  let weighed = 0;
  for (const weight of weights) {
    if (typeof weight !== 'number' || !Number.isFinite(weight) || weight < 0) return null;
    weighed += weight;
  }
  if (!(weighed > 0)) return null;

  const shares = [];
  const order = [];
  let handed = 0;
  weights.forEach((weight, index) => {
    const exact = (units * weight) / weighed;
    const base = Math.floor(exact);
    shares.push(base);
    handed += base;
    order.push({ index, part: exact - base });
  });

  order.sort((a, b) => (b.part - a.part) || (a.index - b.index));
  let left = units - handed;
  for (let i = 0; i < order.length && left > 0; i += 1) {
    shares[order[i].index] += 1;
    left -= 1;
  }
  return shares.map(noNegativeZero);
}

// Minor units of one currency into minor units of another. The rate is read off
// a rate card in major units, so the two minor unit scales are part of the sum.
function convert(units, from, to, rate, options) {
  if (typeof units !== 'number' || !Number.isInteger(units)) return null;
  const fromDigits = currencyDigits(from);
  const toDigits = currencyDigits(to);
  if (fromDigits === null || toDigits === null) return null;
  if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) return null;
  const opts = options && typeof options === 'object' ? options : {};

  const shift = toDigits - fromDigits;
  let scaled = units * rate;
  if (shift > 0) scaled *= Math.pow(10, shift);
  else if (shift < 0) scaled /= Math.pow(10, -shift);
  return roundUnits(scaled, opts.rounding);
}

module.exports = {
  parseAmount,
  roundUnits,
  currencyDigits,
  formatAmount,
  allocate,
  convert,
};

