'use strict';

const { parseAmount, formatAmount, currencyDigits, allocate } = require('./money.js');

function refuse(code, line) {
  const out = { ok: false, code };
  if (line !== undefined) out.line = line;
  return out;
}

function usableQuantity(value) {
  return typeof value === 'number' && Number.isInteger(value) && value > 0;
}

// Prices an invoice in its own currency. The screen shows one problem at a
// time, so the order the checks run in is load bearing: currency, then lines,
// then each line in turn, then the discount.
function totalInvoice(invoice) {
  const inv = invoice && typeof invoice === 'object' ? invoice : {};
  const currency = inv.currency;
  if (currencyDigits(currency) === null) return refuse('bad_currency');

  const lines = inv.lines;
  if (!Array.isArray(lines) || lines.length === 0) return refuse('no_lines');

  const subtotals = [];
  let gross = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i] && typeof lines[i] === 'object' ? lines[i] : {};
    const units = parseAmount(line.amount, currency);
    if (units === null) return refuse('bad_amount', i + 1);
    if (!usableQuantity(line.quantity)) return refuse('bad_quantity', i + 1);
    const subtotal = units * line.quantity;
    subtotals.push(subtotal);
    gross += subtotal;
  }

  if (inv.discount === undefined) {
    return { ok: true, currency, total: gross, display: formatAmount(gross, currency) };
  }

  const discount = parseAmount(inv.discount, currency);
  if (discount === null || discount < 0) return refuse('bad_discount');
  if (discount > gross) return refuse('discount_too_large');

  const weights = subtotals.map((subtotal) => Math.abs(subtotal));
  const shares = weights.some((weight) => weight > 0)
    ? allocate(discount, weights)
    : subtotals.map(() => 0);
  const total = gross - discount;
  return {
    ok: true,
    currency,
    total,
    display: formatAmount(total, currency),
    discount,
    lineDiscounts: shares,
  };
}

module.exports = { totalInvoice };
